//! Extends the genuine historical winner ledger; only certificate corruption
//! is a deliberate host fixture. No input asset or accrued reward is injected.
use crate::{support::*,mining,ori};
fn at(seeds:&[&[u8]])->Pubkey{Pubkey::find_program_address(seeds,&PROGRAM).0}
fn activation(w:&[u8;32],seq:u64)->Pubkey{let id=hash(11,&[&domain(),&ori::FAMILY,w,&seq.to_le_bytes()]);at(&[b"bio",b"activation",&id])}
fn actual_history(vm:&Mollusk,mut a:Vec<(Pubkey,Account)>,bio:Pubkey,bytes:&[u8])->(Vec<(Pubkey,Account)>,Vec<u8>){
 let aid=artifact_id(702,BOOT,bytes);let mut p=vec![1];p.extend_from_slice(bio.as_ref());p.extend_from_slice(&aid);p.extend_from_slice(&Sha256::digest(bytes));p.extend_from_slice(&(bytes.len()as u32).to_le_bytes());p.extend_from_slice(&read64(&account(&a,ori::verify_address()).data,380).to_le_bytes());p.extend_from_slice(&ori::RENT.to_le_bytes());let mut m=prefix();m.extend([AccountMeta::new_readonly(artifact_address(&aid),false),AccountMeta::new(ori::verify_address(),false),AccountMeta::new_readonly(root_address(&bio),false)]);let r=vm.process_instruction(&Instruction{program_id:PROGRAM,accounts:m,data:wire(37,next_nonce(&a,BOOT),&p)},&a);assert_eq!(r.raw_result,Ok(()));a=r.resulting_accounts;let mut prior=r.return_data;
 while u16::from_le_bytes(prior[16..18].try_into().unwrap())<73{let cur=u16::from_le_bytes(prior[16..18].try_into().unwrap());let mut p=aid.to_vec();p.extend_from_slice(&prior[8..16]);p.extend_from_slice(&cur.to_le_bytes());p.extend_from_slice(&[((73-cur).min(2))as u8,0]);p.extend_from_slice(&prior[30..62]);p.extend_from_slice(&ori::RENT.to_le_bytes());let mut m=prefix();m.extend([AccountMeta::new_readonly(artifact_address(&aid),false),AccountMeta::new(ori::verify_address(),false)]);let r=vm.process_instruction(&Instruction{program_id:PROGRAM,accounts:m,data:wire(31,next_nonce(&a,BOOT),&p)},&a);assert_eq!(r.raw_result,Ok(()));a=r.resulting_accounts;prior=r.return_data;}
 assert_eq!(ori::read_failure(&prior),0);assert_eq!(read64(&prior,22),318);(a,prior)
}

