 let start=ori::reward_start(&a);let old_debt=account(&a,mining::position(bio,0)).clone();let immutable_winner=account(&a,winner).clone();a=mining::stake(vm,a,bio,BOOT,BOOT);let act=activation(&wid,1);let dir=at(&[b"bio",b"mining-k",&1u64.to_le_bytes()]);let event=read64(&account(&a,pda(b"mining")).data,160);for key in[act,dir,mining::event_key(event)]{add_empty(&mut a,key);}let mut p=wid.to_vec();p.extend_from_slice(&read64(&account(&a,ori::named(b"task")).data,229).to_le_bytes());p.extend_from_slice(&ori::RENT.to_le_bytes());let mut m=prefix();m.extend([AccountMeta::new(ori::named(b"task"),false),AccountMeta::new(ori::named(b"k-slot"),false),AccountMeta::new_readonly(winner,false),AccountMeta::new_readonly(root_address(&bio),false),AccountMeta::new(mining::root_reg(bio),false),AccountMeta::new_readonly(mining::position(bio,1),false),AccountMeta::new(act,false),AccountMeta::new(dir,false),AccountMeta::new(pda(b"mining"),false),AccountMeta::new(mining::event_key(event),false),AccountMeta::new_readonly(activation(&wid,0),false)]);let activated=vm.process_instruction(&Instruction{program_id:PROGRAM,accounts:m,data:wire(36,next_nonce(&a,BOOT),&p)},&a);println!("REAL_K_REACTIVATE cu={} raw={:?}",activated.compute_units_consumed,activated.raw_result);assert_eq!(activated.raw_result,Ok(()));a=activated.resulting_accounts;assert_eq!(read64(&account(&a,act).data,304),437);
