 account_mut(&mut a,root_address(&bio)).data[719..727].copy_from_slice(&319u64.to_le_bytes());let(next,prior)=actual_history(vm,a,bio,bytes);a=next;let index=14;assert_eq!(&account(&a,ori::knowledge(index)).data[269..301],bio.as_ref());let count=read64(&account(&a,ori::named(b"task")).data,164);let epoch=read64(&account(&a,ori::named(b"task")).data,239);let round=((vm.sysvars.clock.unix_timestamp-start)/259200)as u64;let e=read64(&account(&a,pda(b"mining")).data,160);for key in[ori::safety(epoch+1),ori::round(round),ori::knowledge(count),mining::event_key(e),mining::event_key(e+1)]{add_empty(&mut a,key);}
 let aid=artifact_id(702,BOOT,bytes);let mut p=ori::FAMILY.to_vec();p.extend_from_slice(&1u32.to_le_bytes());p.extend_from_slice(&index.to_le_bytes());p.extend_from_slice(&epoch.to_le_bytes());p.extend_from_slice(&aid);p.extend_from_slice(&Sha256::digest(bytes));p.extend_from_slice(&(bytes.len()as u32).to_le_bytes());p.extend_from_slice(BOOT.as_ref());p.extend_from_slice(&ori::RENT.to_le_bytes());let mut m=prefix();m.extend([AccountMeta::new(ori::named(b"task"),false),AccountMeta::new(ori::named(b"k-slot"),false),AccountMeta::new(pda(b"mining"),false),AccountMeta::new(ori::knowledge(index),false),AccountMeta::new_readonly(artifact_address(&aid),false),AccountMeta::new_readonly(ori::verify_address(),false),AccountMeta::new_readonly(root_address(&bio),false),AccountMeta::new(ori::safety(epoch+1),false),AccountMeta::new(ori::round(round),false),AccountMeta::new(ori::knowledge(count),false),AccountMeta::new(ori::disclosure(&design),false),AccountMeta::new(mining::root_reg(bio),false),AccountMeta::new(mining::position(bio,1),false),AccountMeta::new(mining::event_key(e+1),false),AccountMeta::new(act,false),AccountMeta::new(mining::event_key(e),false)]);let ix=Instruction{program_id:PROGRAM,accounts:m,data:wire(38,next_nonce(&a,BOOT),&p)};let before=a.clone();let mut fail=ix.clone();fail.data=wire(255,next_nonce(&a,BOOT)+1,&[]);fail.accounts=prefix();let rollback=vm.process_transaction_instructions(&[ix.clone(),fail],&a,Some(&BOOT));assert!(rollback.raw_result.is_err());assert_eq!(rollback.resulting_accounts,before);
 let lab=ata(&pda(b"lab-mint"),&BOOT);let balance=read64(&account(&a,lab).data,64);let result=vm.process_instruction(&ix,&a);println!("REAL_ROOT_FAULT_WITH_K cu={} raw={:?}",result.compute_units_consumed,result.raw_result);assert_eq!(result.raw_result,Ok(()));a=result.resulting_accounts;assert_eq!(read64(&account(&a,lab).data,64),balance);assert_eq!(account(&a,winner),&immutable_winner);assert_eq!(account(&a,mining::position(bio,0)),&old_debt);assert_eq!(account(&a,mining::root_reg(bio)).data[323],1);assert_eq!(account(&a,mining::position(bio,1)).data[277],1);assert_eq!(read64(&account(&a,mining::position(bio,1)).data,278),439);assert_eq!(read64(&account(&a,act).data,313),439);assert_eq!(account(&a,ori::named(b"task")).data[238],1);assert_eq!(account(&a,ori::knowledge(index)).data[365],1);assert_eq!(account(&a,ori::knowledge(count)).data[268],2);assert_eq!(account(&a,ori::safety(epoch+1)).data[200],0);assert_eq!(read64(&account(&a,ori::safety(epoch+1)).data,433),index);
 clock_at(vm,&mut a,start+440*3600+1);a=mining::settle_through(vm,a,440);let owed=read64(&account(&a,mining::position(bio,1)).data,351);assert_eq!(owed,1_712_328);a=mining::claim(vm,a,bio,1,BOOT);assert_eq!(read64(&account(&a,lab).data,64),balance+owed);assert_eq!(account(&a,winner),&immutable_winner);assert_eq!(account(&a,mining::position(bio,0)),&old_debt);assert_eq!(read64(&account(&a,pda(b"lab-mint")).data,36),N-48_000_000);println!("REAL_ROOT_FAULT_COMPLETE priorDebtIntact=true historicalWinnerIntact=true accruedPaid={owed} ends439 newMint=0");let _=prior;a
